const bundleCatalog=[...serviceBundles,...writingBundles];
export function purchaseSelection(plan,quantity=1,kind='member'){
 const selected=(kind==='bundle'?bundleCatalog:memberPlans.filter(p=>!p.available)).find(p=>p.id===plan)||(kind==='bundle'?serviceBundles[0]:memberPlans[1]);
 const n=Number(quantity);return {plan:selected,quantity:Number.isInteger(n)&&n>=1&&n<=365?n:1,kind:kind==='bundle'?'bundle':'member',price:null,referencePrice:selected.price,paymentEnabled:false};
}
const commerceOptions=[
 {id:'plans',title:'会员订阅',icon:'diamond',scene:'适合持续写作与研究',caption:'按周期组合会员权益'},
 {id:'recharge',title:'积分购买',icon:'plus',scene:'适合按需使用单项服务',caption:'科研积分，按任务消耗'},
 {id:'bundles',title:'套餐购买',icon:'grid',scene:'适合阶段性论文任务',caption:'查降与写作服务组合'}
];
function navigation(tab){return `<div class="commerce-center-navigation"><nav class="commerce-tabs commerce-center-tabs" aria-label="购买方式">${commerceOptions.map(o=>`<a class="commerce-center-tab" href="#membership/${o.id}" ${tab===o.id?'aria-current="page"':''}><span class="commerce-center-tab-icon">${icon(o.icon,22)}</span><span class="commerce-center-tab-copy"><strong>${o.title}</strong><span>${o.scene}</span></span><span class="commerce-center-tab-state">${tab===o.id?'当前方案':icon('arrow',17)}</span></a>`).join('')}</nav><div class="commerce-center-subnav"><span>按使用习惯，选择适合你的支持方式。</span><a href="#membership/redeem" ${tab==='redeem'?'aria-current="page"':''}>已有兑换码？去兑换 ${icon('arrow',14)}</a></div></div>`;}
function heading(tab){return `${toolBanner('membership',{title:'会员与购买中心',description:'持续研究选会员，按需使用选积分，阶段任务选套餐。',actions:`<a class="btn secondary" href="#membership?scope=account">账户权益 ${icon('arrow',16)}</a><a class="btn secondary" href="#orders">订单记录</a>`})}<div class="commerce-center-availability" role="note"><span>${icon('clock',16)}方案设计预览</span><p>暂未开放购买。订阅周期、科研积分兑换比例及具体服务规则将在正式开放前公布。</p></div>${navigation(tab)}`;}
function rules(){return `<div class="purchase-notice commerce-center-rules">${icon('shield',18)}<p>当前仅供查看参考方案，不创建订单、扣款或发放权益；不启用自动续费。实际服务范围、有效期及退款规则以正式开放时公布的内容为准。</p></div>`;}
const memberAudience={free:'初次体验，整理已有研究材料',standard:'有单项论文辅助需求的学生',advanced:'需要跨阶段研究辅助的用户',pro:'需要多类科研工具支持的用户'};
const bundleAudience={rewrite:'查重与重复内容修改',reduce:'AI 表达调整与文本修改',dual:'重复内容与 AI 表达协同处理',junior:'专科论文与答辩准备',bachelor:'本科论文与答辩准备',master:'硕士论文与研究汇报',doctor:'博士论文与研究汇报'};
function card(plan,kind){const audience=kind==='bundle'?bundleAudience[plan.id]:memberAudience[plan.id];return `<article class="purchase-plan commerce-center-plan ${plan.featured||plan.id==='advanced'?'featured':''} ${plan.available?'commerce-center-plan-free':''}"><div class="purchase-plan-top"><span class="purchase-plan-icon">${icon(plan.available?'user':kind==='bundle'?'grid':'diamond',24)}</span><span class="purchase-status">${plan.available?'当前可用':plan.featured||plan.id==='advanced'?'重点方案':'方案预览'}</span></div><h3>${plan.name}</h3><p class="commerce-center-audience">${audience}</p><div class="purchase-price"><b>${plan.available?'免费':'¥'+plan.price}</b><span>${plan.available?'本地功能体验':kind==='bundle'?'参考价 / 套':'参考价 · 计价单位待确认'}</span></div><div class="commerce-center-feature-label">${plan.available?'可用功能':'规划权益'}</div><ul>${plan.features.map(f=>`<li><span aria-hidden="true">✓</span>${f.replace(/^规划：/,'')}</li>`).join('')}</ul>${plan.available?'<a class="btn secondary full" href="#home">继续免费体验</a>':`<a class="btn ${plan.id==='advanced'||plan.id==='reduce'?'primary':'secondary'} full" href="#membership/checkout?kind=${kind}&plan=${plan.id}&quantity=1">查看方案 ${icon('arrow',16)}</a>`}</article>`;}
function purchaseWays(){return `<section class="commerce-center-methods" aria-labelledby="commerce-ways-heading"><div class="commerce-center-section-title"><h2 id="commerce-ways-heading">三种方式，按你的研究节奏选择</h2><p>会员、积分与套餐分别满足持续、零散和集中使用的需要。</p></div><div class="commerce-center-method-grid">${commerceOptions.map(o=>`<article><span>${icon(o.icon,20)}</span><div><h3>${o.title}</h3><p>${o.caption}</p><small>${o.scene}</small></div></article>`).join('')}</div></section>`;}
function purchaseFAQ(){return `<section class="card purchase-faq commerce-center-faq"><h2>购买前，了解这些就够了</h2><details><summary>会员、积分和套餐有什么区别？</summary><p>会员面向持续使用，按周期提供组合权益；科研积分面向按需使用；套餐把特定阶段的服务按次数组合。最终计费单位、额度与叠加规则将在开放前公布。</p></details><details><summary>现在能购买吗？是否自动续费？</summary><p>当前展示方案设计，尚未开放购买，也不启用自动续费。已有账户内容与实际权益可在“账户权益”中查看。</p></details><details><summary>购买后能保证检测结果或论文通过吗？</summary><p>工具用于辅助研究与内容整理，不承诺检测分数或论文通过。具体服务范围、有效期、退款与开票规则将在正式开放前说明。</p></details></section>`;}
export function mountMemberPlans(){
 $('.dashboard').innerHTML=heading('plans')+`<section class="commerce-center-section"><div class="purchase-section-head commerce-center-section-title"><div><span class="commerce-center-eyebrow">MEMBERSHIP</span><h2>为持续研究，选择一份长期支持</h2><p>从免费体验到不同会员等级，按实际需求了解规划权益。</p></div><span class="commerce-center-unit-note">计价单位与订阅周期待确认</span></div><div class="purchase-plans commerce-member-plans commerce-center-plan-grid">${memberPlans.map(p=>card(p,'member')).join('')}</div></section>`+purchaseWays()+purchaseFAQ();
}
export function mountCommerce(tab){
 if(tab==='bundles'){const mode=new URLSearchParams(location.hash.split('?')[1]||'').get('mode')||'detect';const plans=mode==='writing'?writingBundles:serviceBundles;const title=mode==='writing'?'写作套餐':'查降套餐';$('.dashboard').innerHTML=heading(tab)+`<section class="commerce-center-section"><div class="purchase-section-head commerce-center-section-title"><div><span class="commerce-center-eyebrow">RESEARCH BUNDLES</span><h2>围绕一项任务，组合需要的服务</h2><p>按论文阶段选择套餐，先了解每项服务与包含次数。</p></div><nav class="purchase-kind-tabs commerce-center-kind-tabs" aria-label="套餐类型"><a href="#membership/bundles?mode=detect" ${mode==='detect'?'aria-current="page"':''}>查降套餐</a><a href="#membership/bundles?mode=writing" ${mode==='writing'?'aria-current="page"':''}>写作套餐</a></nav></div><div class="commerce-center-bundle-caption"><h3>${title}</h3><p>${mode==='writing'?'覆盖论文、开题、文献综述与答辩 PPT 的规划服务。':'适合查重、AIGC 检测与文本修改阶段的规划服务。'}</p></div><div class="purchase-plans commerce-center-plan-grid ${mode==='writing'?'commerce-writing-plans':''}">${plans.map(p=>card(p,'bundle')).join('')}</div><p class="commerce-center-fineprint">套餐有效期、字数上限及实际交付范围待正式规则确认。</p></section>`+purchaseFAQ();return;}
 if(tab==='recharge'){
 const rechargeParams=new URLSearchParams(location.hash.split('?')[1]||''),returnTarget=rechargeParams.get('return')||'',returnToWriting=['writing','proposal','summary','taskbook','article','course','practice','topic','questionnaire','analysis','quick'].includes(returnTarget),returnDraft=rechargeParams.get('draft'),returnHref=returnDraft?`#draft/${encodeURIComponent(returnDraft)}`:`#tool/${returnToWriting?returnTarget:'writing'}`;
 $('.dashboard').innerHTML=heading(tab)+`<section class="card purchase-detail commerce-form commerce-surface commerce-center-form"><header class="commerce-surface-heading"><div><span class="commerce-center-eyebrow">RESEARCH CREDITS</span><h2>科研积分，按需选择</h2><p>适合零散任务，无需先选择整套服务。</p>${returnToWriting?`<a class="commerce-return-writing" href="${returnHref}">${returnTarget==='proposal'?'← 返回开题报告生成确认':returnTarget==='summary'?'← 返回文献综述生成确认':returnTarget==='taskbook'?'← 返回任务书生成确认':returnTarget==='article'?'← 返回期刊文章生成确认':returnTarget==='course'?'← 返回课程作业生成确认':returnTarget==='practice'?'← 返回实践报告生成确认':returnTarget==='topic'?'← 返回课题思路生成确认':returnTarget==='questionnaire'?'← 返回问卷设计生成确认':returnTarget==='analysis'?'← 返回数据分析生成确认':returnTarget==='quick'?'← 返回快速写作生成确认':'← 返回生成版本确认'}</a>`:''}</div></header><div class="commerce-form-body"><div><h3>选择积分数量</h3><p class="commerce-help">以下为数量选择示意，不代表人民币金额。</p><div class="commerce-amounts">${[30,50,100].map(n=>`<button class="btn secondary" data-credit="${n}" aria-pressed="false"><b>${n}</b><small>科研积分</small></button>`).join('')}</div><label for="credit-custom">自定义数量</label><input id="credit-custom" type="number" min="1" max="100000" step="1" placeholder="输入 1～100000 的整数数量"><p id="credit-summary" role="status">请选择积分数量，兑换金额待正式规则确认。</p></div><aside class="commerce-side-info commerce-center-credit-guide"><span class="commerce-center-guide-icon">${icon('plus',24)}</span><h3>按任务使用，消耗先确认</h3><p>积分将用于已开放的在线服务，具体支持范围与每次消耗会在任务确认时说明。</p><div><span>兑换比例</span><b>待公布</b></div><div><span>有效期与退回规则</span><b>待公布</b></div></aside></div><button class="btn primary" disabled>暂未开放购买</button><p class="member-caption">选择数量不会扣款或变更账户积分。</p></section>`+purchaseFAQ();
 const input=$('#credit-custom');const show=()=>{const n=Number(input.value);$('#credit-summary').textContent=Number.isInteger(n)&&n>=1&&n<=100000?`已选 ${n} 科研积分，兑换金额待正式规则确认。`:'请输入 1～100000 的整数积分数量。';document.querySelectorAll('[data-credit]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.credit)===n)));};document.querySelectorAll('[data-credit]').forEach(b=>b.onclick=()=>{input.value=b.dataset.credit;show();});input.oninput=show;return;
 }
 $('.dashboard').innerHTML=heading('redeem')+`<section class="card purchase-detail commerce-form commerce-surface commerce-center-form"><header class="commerce-surface-heading"><div><span class="commerce-center-eyebrow">REDEEM CODE</span><h2>兑换已有权益</h2><p>用于兑换正式发放的会员、套餐或科研积分。</p></div></header><div class="commerce-form-body"><div><label for="member-code">输入兑换码</label><input id="member-code" type="text" maxlength="64" autocomplete="off" placeholder="输入 6～64 位兑换码"><button id="code-check" class="btn secondary">检查输入格式</button><p id="code-message" role="status">兑换尚未开放；此处仅检查格式，不验证或发放权益。</p></div><aside class="commerce-side-info commerce-center-credit-guide"><span class="commerce-center-guide-icon">${icon('diamond',24)}</span><h3>兑换说明</h3><p>具体兑换内容与有效期，以正式发放时附带的说明为准。请勿向他人公开兑换码。</p></aside></div><button class="btn primary" disabled>暂未开放兑换</button></section>`;$('#code-check').onclick=()=>{$('#code-message').textContent=/^[A-Za-z0-9-]{6,64}$/.test($('#member-code').value.trim())?'输入格式符合要求；兑换服务未开放，尚未验证有效性，也未发放权益。':'请使用 6～64 位字母、数字或连字符；实际格式以正式发放规则为准。';};
}
export function mountMemberCheckout(planId,quantity,kind){
 const s=purchaseSelection(planId,quantity,kind),p=s.plan;const back=s.kind==='bundle'?'bundles':'plans';
 $('.dashboard').innerHTML=`<div class="hub-heading"><div><h1>确认购买方案</h1><p>当前仅预览方案，支付尚未开放。</p></div><a class="btn secondary" href="#membership/${back}">重新选择套餐</a></div><div class="purchase-checkout-grid"><section class="card purchase-detail"><div class="purchase-detail-heading"><span class="purchase-plan-icon">${icon('diamond',28)}</span><h2>${p.name}</h2><span class="purchase-status">定价预览</span></div><dl class="purchase-summary"><div><dt>参考价格</dt><dd>¥${p.price}${s.kind==='bundle'?' / 套':' · 计价单位待确认'}</dd></div><div><dt>有效期、字数限制与额度规则</dt><dd>待确认</dd></div><div><dt>自动续费</dt><dd>不启用</dd></div></dl><label for="purchase-quantity">购买数量${s.kind==='member'?'（计价单位待确认）':'（套）'}</label><input id="purchase-quantity" type="number" min="1" max="365" step="1" value="${s.quantity}"><p id="quantity-error" role="status"></p><h3>方案内容（待开放）</h3><ul class="purchase-checkout-features">${p.features.map(f=>`<li>${icon('shield',16)}${f}</li>`).join('')}</ul><div class="purchase-payment-options"><span>微信支付 · 待接入</span><span>支付宝 · 待接入</span></div></section><aside class="card purchase-confirm"><span class="purchase-confirm-label">方案确认</span><h2>${p.name}</h2><dl><div><dt>选择数量</dt><dd id="selected-quantity">${s.quantity}</dd></div><div><dt>参考合计</dt><dd id="reference-total">¥${p.price*s.quantity}</dd></div><div><dt>实际应付</dt><dd>待正式规则确认</dd></div></dl><div class="purchase-payment-state">${icon('clock',20)}<div><b>支付尚未开放</b><p>参考合计不构成正式报价或订单。</p></div></div><button class="btn primary full" disabled>暂未开放支付</button><a class="btn secondary full" href="#home">继续免费体验</a><p class="purchase-confirm-note">当前未创建订单、未扣款、未开通会员。服务范围、退款与发票规则将在开放前确认。</p></aside></div>`+rules();
 $('#purchase-quantity').oninput=()=>{const n=Number($('#purchase-quantity').value);if(!Number.isInteger(n)||n<1||n>365){$('#quantity-error').textContent='请输入 1～365 的整数数量。';$('#reference-total').textContent='—';$('#selected-quantity').textContent='待修正';return;}window.history.replaceState(null,'',`#membership/checkout?kind=${s.kind}&plan=${p.id}&quantity=${n}`);$('#quantity-error').textContent='';$('#reference-total').textContent='¥'+n*p.price;$('#selected-quantity').textContent=String(n);};
}
